import 'package:flutter/material.dart'; import '../models/models.dart'; import '../providers/app_state.dart'; import '../widgets/common.dart';
class DetailScreen extends StatefulWidget{final AppState state;final Task task;const DetailScreen({super.key,required this.state,required this.task});@override State<DetailScreen> createState()=>_DetailScreenState();}
class _DetailScreenState extends State<DetailScreen>{late Task t;final comment=TextEditingController();@override void initState(){super.initState();t=widget.task;}@override Widget build(BuildContext c){return ListView(padding:const EdgeInsets.all(24),children:[TextButton.icon(onPressed:()=>Navigator.pop(c),icon:const Icon(Icons.arrow_back),label:const Text('Tasks')),Text('#${t.id} ${t.title}',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:8),Wrap(spacing:8,children:[StatusBadge(enumName(t.status),Colors.green),StatusBadge(enumName(t.priority),Colors.orange)]),const SizedBox(height:24),GitCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Description',style:Theme.of(c).textTheme.titleLarge),const Divider(),Text(t.description),const SizedBox(height:20),Text('Labels',style:Theme.of(c).textTheme.titleMedium),const SizedBox(height:8),Wrap(spacing:6,children:widget.state.workspace.labels.where((l)=>t.labelIds.contains(l.id)).map((l)=>StatusBadge(l.name,Color(int.parse(l.color.substring(1),radix:16)+0xFF000000))).toList()),const SizedBox(height:20),Text('Milestone',style:Theme.of(c).textTheme.titleMedium),Text(widget.state.workspace.milestones.firstWhere((m)=>m.id==t.milestoneId).title),const SizedBox(height:20),Text('Subtasks',style:Theme.of(c).textTheme.titleMedium),...t.subtasks.map((s)=>CheckboxListTile(value:s.done,onChanged:(v){setState(()=>s.done=v??false);widget.state.save();},title:Text(s.title),contentPadding:EdgeInsets.zero)),const SizedBox(height:12),Text('Activity',style:Theme.of(c).textTheme.titleLarge),const Divider(),...t.comments.map((x)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(x.author,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(x.body))),TextField(controller:comment,minLines:2,maxLines:4,decoration:const InputDecoration(hintText:'Write a comment')),const SizedBox(height:8),Align(alignment:Alignment.centerRight,child:FilledButton(onPressed:(){if(comment.text.trim().isEmpty)return;setState(()=>t.comments.add(Comment(id:DateTime.now().toIso8601String(),body:comment.text.trim(),author:'You',createdAt:DateTime.now())));comment.clear();widget.state.save();},child:const Text('Comment')))]))]);}}
